from pyspark.sql import functions as F

STATUSES = ["draft", "open", "paid", "overdue", "void"]


def make_tasks(invoices, invoice_lines):
    # Tonight's tasks: each name maps to (function, the tasks it needs). Don't change this.
    def bronze_invoices():
        return invoices.withColumn("_batch_id", F.lit(7))

    def line_totals():
        return invoice_lines.groupBy("invoice_id").agg(F.sum("line_amount").alias("lines_total"))

    def checked(bronze, totals):
        problem = (
            F.when(F.col("account_id").isNull(), "no account")
            .when(~F.coalesce(F.col("status").isin(STATUSES), F.lit(False)), "unknown status")
            .when(~F.coalesce(F.col("total_amount") == F.col("lines_total"), F.lit(False)), "total differs from its lines")
        )
        return bronze.join(totals, on="invoice_id", how="left").withColumn("_problem", problem)

    def silver_invoices(bronze_invoices, line_totals):
        rows = checked(bronze_invoices, line_totals)
        gate(rows)  # raises when too many rows break a rule
        return rows.filter(F.col("_problem").isNull()).select(bronze_invoices.columns)

    def quarantine(bronze_invoices, line_totals):
        return checked(bronze_invoices, line_totals).filter(F.col("_problem").isNotNull())

    def fact_invoices(silver_invoices):
        return silver_invoices.dropDuplicates(["invoice_id"])

    def gold_revenue(fact_invoices):
        billed = fact_invoices.filter(~F.col("status").isin("draft", "void"))
        return billed.groupBy(F.date_format("invoice_date", "yyyy-MM").alias("month")).agg(F.sum("total_amount").alias("revenue"))

    def checks(gold_revenue, fact_invoices):
        gold = gold_revenue.agg(F.sum("revenue").alias("gold_total"))
        fact = fact_invoices.filter(~F.col("status").isin("draft", "void")).agg(F.sum("total_amount").alias("fact_total"))
        return gold.crossJoin(fact).withColumn("agree", F.col("gold_total").eqNullSafe(F.col("fact_total")))

    return {
        "bronze_invoices": (bronze_invoices, []),
        "line_totals": (line_totals, []),
        "silver_invoices": (silver_invoices, ["bronze_invoices", "line_totals"]),
        "quarantine": (quarantine, ["bronze_invoices", "line_totals"]),
        "fact_invoices": (fact_invoices, ["silver_invoices"]),
        "gold_revenue": (gold_revenue, ["fact_invoices"]),
        "checks": (checks, ["gold_revenue", "fact_invoices"]),
    }


def run_order(deps):
    # Lesson 77's order: a task runs once everything it needs has run. Don't change this.
    order = []
    while len(order) < len(deps):
        ready = [t for t in deps if t not in order and all(d in order for d in deps[t])]
        if not ready:
            raise ValueError("these tasks wait on each other: " + ", ".join(t for t in deps if t not in order))
        order += ready
    return order


